const rows = $input.all().map((item) => item.json || {});
const values = {};
for (const row of rows) {
  if (typeof row.name === 'string') values[row.name] = row.data;
}

const required = [
  'WEATHERAPI_API_KEY',
  'SCHOOL_LATITUDE',
  'SCHOOL_LONGITUDE',
  'TIMEZONE',
  'NOTIFICATIONS_BASE_URL',
  'NOTIFICATIONS_WEATHER_TOPIC',
  'NOTIFICATIONS_INFRA_ISSUES_TOPIC',
];
const missing = required.filter((key) => values[key] === undefined || values[key] === null || String(values[key]).trim() === '');
if (missing.length) throw new Error(`Missing required public.key_value_store keys: ${missing.join(', ')}`);

const apiKey = String(values.WEATHERAPI_API_KEY).trim();
const latitude = Number(values.SCHOOL_LATITUDE);
const longitude = Number(values.SCHOOL_LONGITUDE);
const timezone = String(values.TIMEZONE).trim();
const notificationsBaseUrl = String(values.NOTIFICATIONS_BASE_URL).trim().replace(/\/+$/, '');
const notificationsUser = String(values.NOTIFICATIONS_USER ?? '').trim();
const notificationsPassword = String(values.NOTIFICATIONS_PASSWORD ?? '');
const weatherTopic = String(values.NOTIFICATIONS_WEATHER_TOPIC).trim();
const infraTopic = String(values.NOTIFICATIONS_INFRA_ISSUES_TOPIC).trim();

if (!Number.isFinite(latitude) || latitude < -90 || latitude > 90) throw new Error('Configured latitude is invalid');
if (!Number.isFinite(longitude) || longitude < -180 || longitude > 180) throw new Error('Configured longitude is invalid');
if (!/^https?:\/\/[^\s/]+(?:\/.*)?$/i.test(notificationsBaseUrl)) throw new Error('NOTIFICATIONS_BASE_URL must be an absolute HTTP(S) URL');
if ((notificationsUser && !notificationsPassword) || (!notificationsUser && notificationsPassword)) {
  throw new Error('NOTIFICATIONS_USER and NOTIFICATIONS_PASSWORD must either both be configured or both be empty');
}
try { new Intl.DateTimeFormat('en-US', { timeZone: timezone }).format(new Date()); }
catch { throw new Error(`TIMEZONE is not a valid IANA time zone: ${timezone}`); }

const localParts = Object.fromEntries(
  new Intl.DateTimeFormat('en-CA', {
    timeZone: timezone,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23',
  }).formatToParts(new Date()).filter((p) => p.type !== 'literal').map((p) => [p.type, p.value])
);
const localDate = `${localParts.year}-${localParts.month}-${localParts.day}`;
const tomorrowDate = (() => {
  const d = new Date(Date.UTC(Number(localParts.year), Number(localParts.month) - 1, Number(localParts.day) + 1));
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`;
})();

return [{ json: {
  weatherApi: {
    apiKey,
    query: `${latitude},${longitude}`,
    baseUrl: 'https://api.weatherapi.com/v1',
  },
  notifications: {
    baseUrl: notificationsBaseUrl,
    user: notificationsUser,
    password: notificationsPassword,
    weatherTopic,
    infraTopic,
  },
  timezone,
  current: {
    conditionTtlSeconds: 15 * 60,
    apiErrorMarkerKey: 'weather-notifier:active:v1:api-error:current',
    apiErrorTtlSeconds: 15 * 60,
  },
  daily: {
    dueNow: Number(localParts.hour) >= 23,
    targetDate: tomorrowDate,
    markerKey: `weather-notifier:sent:v1:daily:${tomorrowDate}`,
    markerTtlSeconds: 3 * 24 * 60 * 60,
    apiErrorMarkerKey: 'weather-notifier:active:v1:api-error:forecast',
    apiErrorTtlSeconds: 15 * 60,
  },
  local: {
    date: localDate,
    hour: Number(localParts.hour),
    minute: Number(localParts.minute),
  },
} }];

const cfg = $('Format & Validate Config').first().json;
const startedAt = new Date().toISOString();
try {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: `${cfg.weatherApi.baseUrl}/current.json`,
    qs: { key: cfg.weatherApi.apiKey, q: cfg.weatherApi.query, aqi: 'no' },
    json: true,
    timeout: 20000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  const statusCode = Number(res?.statusCode || 0);
  let body = res?.body;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch { body = null; }
  }
  if (statusCode < 200 || statusCode >= 300) {
    return [{ json: { success: false, endpoint: 'current', statusCode, error: body?.error?.message || `WeatherAPI returned HTTP ${statusCode || 'unknown'}`, startedAt } }];
  }
  if (!body?.current?.condition || !body?.location) {
    return [{ json: { success: false, endpoint: 'current', statusCode, error: 'WeatherAPI current response was missing expected fields', startedAt } }];
  }
  return [{ json: { success: true, endpoint: 'current', statusCode, data: body, startedAt } }];
} catch (error) {
  return [{ json: { success: false, endpoint: 'current', statusCode: null, error: error?.message || String(error), startedAt } }];
}

const cfg = $('Format & Validate Config').first().json;
const fetched = $('Fetch Current Weather').first().json;
const current = fetched.data.current || {};
const condition = current.condition || {};
const code = Number(condition.code);
const quietCodes = new Set([1000, 1003, 1006, 1009, 1030, 1135, 1147]);
const reportable = Number.isFinite(code) && !quietCodes.has(code);
const iconRaw = String(condition.icon || '').trim();
const iconUrl = iconRaw.startsWith('//') ? `https:${iconRaw}` : iconRaw;
const observedAt = current.last_updated || fetched.data.location?.localtime || null;
const key = `weather-notifier:active:v1:condition:${Number.isFinite(code) ? code : 'unknown'}`;
const details = [
  `Condition: ${condition.text || 'Unknown'}`,
  Number.isFinite(Number(current.temp_c)) ? `Temperature: ${Number(current.temp_c).toFixed(1)}°C${Number.isFinite(Number(current.feelslike_c)) ? ` (feels like ${Number(current.feelslike_c).toFixed(1)}°C)` : ''}` : null,
  Number.isFinite(Number(current.precip_mm)) ? `Precipitation: ${Number(current.precip_mm).toFixed(1)} mm` : null,
  Number.isFinite(Number(current.humidity)) ? `Humidity: ${Math.round(Number(current.humidity))}%` : null,
  Number.isFinite(Number(current.wind_kph)) ? `Wind: ${Number(current.wind_kph).toFixed(0)} km/h${current.wind_dir ? ` ${current.wind_dir}` : ''}${Number.isFinite(Number(current.gust_kph)) ? `, gusts ${Number(current.gust_kph).toFixed(0)} km/h` : ''}` : null,
  Number.isFinite(Number(current.vis_km)) ? `Visibility: ${Number(current.vis_km).toFixed(1)} km` : null,
  observedAt ? `Observed: ${observedAt}` : null,
].filter(Boolean);

return [{ json: {
  reportable,
  conditionCode: code,
  conditionText: condition.text || 'Unknown weather condition',
  markerKey: key,
  markerValue: JSON.stringify({ code, condition: condition.text || null, lastObservedAt: observedAt, refreshedAt: new Date().toISOString() }),
  ttlSeconds: cfg.current.conditionTtlSeconds,
  notification: {
    topic: cfg.notifications.weatherTopic,
    title: `Weather alert: ${condition.text || 'Adverse conditions'}`,
    message: details.join('\n'),
    priority: 4,
    tags: ['warning', 'umbrella'],
    icon: iconUrl || null,
    attach: iconUrl || null,
    filename: iconUrl ? 'weather-condition.png' : null,
  },
} }];

const classified = $('Classify Current Conditions').first().json;
const raw = $input.first().json.reportedRaw;
const alreadyReported = raw !== null && raw !== undefined && raw !== '';
return [{ json: { ...classified, alreadyReported } }];

const cfg = $('Format & Validate Config').first().json;
const candidate = $input.first().json || {};
const n = candidate.notification || {};
const body = {
  topic: String(n.topic || ''),
  title: String(n.title || 'Weather notification'),
  message: String(n.message || ''),
  priority: Number(n.priority || 3),
  tags: Array.isArray(n.tags) ? n.tags : ['weather'],
};
if (n.icon) body.icon = String(n.icon);
if (n.attach) body.attach = String(n.attach);
if (n.filename) body.filename = String(n.filename);
if (n.markdown) body.markdown = true;
const headers = { 'Content-Type': 'application/json; charset=utf-8' };
if (cfg.notifications.user && cfg.notifications.password) {
  headers.Authorization = `Basic ${Buffer.from(`${cfg.notifications.user}:${cfg.notifications.password}`, 'utf8').toString('base64')}`;
}
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: cfg.notifications.baseUrl,
    headers,
    body: JSON.stringify(body),
    encoding: 'text',
    timeout: 20000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  const statusCode = Number(res?.statusCode || 0);
  const success = statusCode >= 200 && statusCode < 300;
  return [{ json: { ...candidate, success, statusCode, deliveryError: success ? null : `ntfy returned HTTP ${statusCode || 'unknown'}` } }];
} catch (error) {
  return [{ json: { ...candidate, success: false, statusCode: null, deliveryError: error?.message || String(error) } }];
}

const cfg = $('Format & Validate Config').first().json;
const fetched = $('Fetch Current Weather').first().json;
const raw = $input.first().json.errorMarkerRaw;
const alreadyReported = raw !== null && raw !== undefined && raw !== '';
const markerValue = JSON.stringify({ endpoint: 'current', lastFailureAt: new Date().toISOString(), statusCode: fetched.statusCode || null });
return [{ json: {
  alreadyReported,
  markerKey: cfg.current.apiErrorMarkerKey,
  markerValue,
  ttlSeconds: cfg.current.apiErrorTtlSeconds,
  notification: {
    topic: cfg.notifications.infraTopic,
    title: 'WeatherAPI current request failed',
    message: `The weather current-conditions request failed${fetched.statusCode ? ` with HTTP ${fetched.statusCode}` : ''}. ${String(fetched.error || 'Unknown error').slice(0, 600)}`,
    priority: 4,
    tags: ['warning', 'cloud'],
  },
} }];

