}

const cfg = $('Format & Validate Config').first().json;
const startedAt = new Date().toISOString();
try {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: `${cfg.weatherApi.baseUrl}/forecast.json`,
    qs: { key: cfg.weatherApi.apiKey, q: cfg.weatherApi.query, days: 2, aqi: 'no', alerts: 'no' },
    json: true,
    timeout: 20000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  const statusCode = Number(res?.statusCode || 0);
  let body = res?.body;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch { body = null; }
  }
  if (statusCode < 200 || statusCode >= 300) {
    return [{ json: { success: false, endpoint: 'forecast', statusCode, error: body?.error?.message || `WeatherAPI returned HTTP ${statusCode || 'unknown'}`, startedAt } }];
  }
  const forecastDays = body?.forecast?.forecastday;
  if (!Array.isArray(forecastDays) || forecastDays.length < 1) {
    return [{ json: { success: false, endpoint: 'forecast', statusCode, error: 'WeatherAPI forecast response was missing forecast days', startedAt } }];
  }
  return [{ json: { success: true, endpoint: 'forecast', statusCode, data: body, startedAt } }];
} catch (error) {
  return [{ json: { success: false, endpoint: 'forecast', statusCode: null, error: error?.message || String(error), startedAt } }];
}

const cfg = $('Format & Validate Config').first().json;
const fetched = $('Fetch Tomorrow Forecast').first().json;
const days = fetched.data.forecast?.forecastday || [];
const forecast = days.find((d) => String(d.date) === cfg.daily.targetDate) || days[1] || days[0];
if (!forecast?.day) throw new Error(`Forecast for ${cfg.daily.targetDate} was not present in WeatherAPI response`);
const day = forecast.day;
const routineCodes = new Set([1000, 1003, 1006, 1009]);
const suppressedFogMistCodes = new Set([1030, 1135, 1147]);
const hours = Array.isArray(forecast.hour) ? forecast.hour : [];
const significant = hours.filter((h) => {
  const code = Number(h?.condition?.code);
  const rain = Number(h?.chance_of_rain || 0);
  const snow = Number(h?.chance_of_snow || 0);
  const precip = Number(h?.precip_mm || 0);
  const significantPrecip = rain >= 30 || snow >= 20 || precip > 0;
  if (suppressedFogMistCodes.has(code)) return significantPrecip;
  return significantPrecip || (Number.isFinite(code) && !routineCodes.has(code));
});
const hourLines = significant.map((h) => {
  const time = String(h.time || '').split(' ')[1] || String(h.time || '');
  const code = Number(h?.condition?.code);
  const conditionText = suppressedFogMistCodes.has(code) ? null : (h.condition?.text || 'Weather');
  const bits = [
    conditionText ? `${time} — ${conditionText}` : time,
    Number.isFinite(Number(h.temp_c)) ? `${Number(h.temp_c).toFixed(0)}°C` : null,
    Number(h.chance_of_rain || 0) > 0 ? `rain ${Math.round(Number(h.chance_of_rain))}%` : null,
    Number(h.chance_of_snow || 0) > 0 ? `snow ${Math.round(Number(h.chance_of_snow))}%` : null,
    Number(h.precip_mm || 0) > 0 ? `${Number(h.precip_mm).toFixed(1)} mm` : null,
    Number(h.gust_kph || 0) >= 30 ? `gusts ${Number(h.gust_kph).toFixed(0)} km/h` : null,
  ].filter(Boolean);
  return bits.join(' · ');
});
if (!hourLines.length) hourLines.push('No significant rain, snow, or adverse hourly conditions are expected.');

const dayCode = Number(day.condition?.code);
const suppressDayCondition = suppressedFogMistCodes.has(dayCode);
const iconRaw = suppressDayCondition ? '' : String(day.condition?.icon || '').trim();
const iconUrl = iconRaw.startsWith('//') ? `https:${iconRaw}` : iconRaw;
const summary = [
  suppressDayCondition
    ? `Forecast for ${forecast.date}`
    : `Forecast for ${forecast.date}: ${day.condition?.text || 'Unknown'}`,
  Number.isFinite(Number(day.mintemp_c)) && Number.isFinite(Number(day.maxtemp_c)) ? `Temperature: ${Number(day.mintemp_c).toFixed(0)}–${Number(day.maxtemp_c).toFixed(0)}°C (avg ${Number(day.avgtemp_c || 0).toFixed(0)}°C)` : null,
  `Rain chance: ${Math.round(Number(day.daily_chance_of_rain || 0))}%${Number(day.totalprecip_mm || 0) > 0 ? ` · total precip ${Number(day.totalprecip_mm).toFixed(1)} mm` : ''}`,
  Number(day.daily_chance_of_snow || 0) > 0 ? `Snow chance: ${Math.round(Number(day.daily_chance_of_snow))}%` : null,
  Number.isFinite(Number(day.maxwind_kph)) ? `Max wind: ${Number(day.maxwind_kph).toFixed(0)} km/h` : null,
  Number.isFinite(Number(day.avghumidity)) ? `Average humidity: ${Math.round(Number(day.avghumidity))}%` : null,
  '',
  'Significant hours:',
  ...hourLines,
].filter((v) => v !== null);

return [{ json: {
  markerKey: cfg.daily.markerKey,
  markerValue: JSON.stringify({ targetDate: cfg.daily.targetDate, sentAt: new Date().toISOString() }),
  ttlSeconds: cfg.daily.markerTtlSeconds,
  notification: {
    topic: cfg.notifications.weatherTopic,
    title: `Tomorrow's weather — ${forecast.date}`,
    message: summary.join('\n'),
    priority: 3,
    tags: ['weather', 'calendar'],
    icon: iconUrl || null,
    attach: iconUrl || null,
    filename: iconUrl ? 'weather-forecast.png' : null,
  },
} }];

